-- ============================================================
-- 5. FRIENDSHIPS
-- ============================================================
--
-- Your friendship table requires:
--
-- user_id_low < user_id_high
--
-- So LEAST() and GREATEST() guarantee canonical ordering.
-- ============================================================

INSERT INTO friendships (
    user_id_low,
    user_id_high,
    requested_by,
    status,
    responded_at
)
SELECT
    LEAST(u1.id, u2.id),
    GREATEST(u1.id, u2.id),
    requester.id,
    data.status,
    CASE
        WHEN data.status = 'accepted' THEN NOW()
        WHEN data.status = 'rejected' THEN NOW()
        ELSE NULL
    END
FROM (
    VALUES

