JOIN users u
    ON LOWER(u.email) = LOWER(data.email)

JOIN courses c
    ON c.course_code = data.course_code
    AND c.university_id = u.university_id
    AND c.academic_year = 2004
    AND LOWER(c.semester) = 'fall'

ON CONFLICT DO NOTHING;


